// ── STATS tab (leaders + team + player tables) ────────────────────────────

let statsView: "team" | "players" = "team";
let statsAnimate = false; // entrance animation only on tab/sub-tab switch, not every poll

const LOWER_BETTER = /turnover|penalt|interception|fumbles lost|sacks-yards lost/i;

function statNum(v: string): number | null {
  const s = String(v).trim();
  const clock = s.match(/^(\d+):(\d{2})$/);          // 26:38 time of possession
  if (clock) return Number(clock[1]) * 60 + Number(clock[2]);
  const frac = s.match(/^(\d+)\s*-\s*(\d+)$/);        // 5-12 efficiency, 2-30 penalties
  if (frac) return Number(frac[1]);
  const n = parseFloat(s);
  return isFinite(n) ? n : null;
}

function logoImg(t: NormTeam, cls: string): string {
  return `<img class="${cls}" src="/teams/${encodeURIComponent(t.id)}.png" alt="${escapeHtml(t.abbr)}"` +
    ` data-tid="${escapeHtml(t.id)}" data-tabbr="${escapeHtml(t.abbr)}" onerror="window.__logoFb(this)">`;
}

function buildTeamCompare(g: NormGame): string {
  const bteams: any[] = lastSummary?.boxscore?.teams || [];
  if (bteams.length !== 2) return '<div class="bs-empty">No team stats yet</div>';
  let a = bteams[0], h = bteams[1];
  if (String(a?.team?.id) === g.home.id) { const t = a; a = h; h = t; }
  const ac = railColorOf(g.away, "#d50a0a"), hc = railColorOf(g.home, "#013369");

  const rows: Record<string, { label: string; a?: string; h?: string }> = {};
  (a?.statistics || []).forEach((st: any) => { rows[st.name] = { label: st.label || st.name, a: st.displayValue }; });
  (h?.statistics || []).forEach((st: any) => {
    rows[st.name] = rows[st.name] || { label: st.label || st.name };
    rows[st.name]!.h = st.displayValue;
  });

  let out = `<div class="ts-head"><span class="ts-head-team">${logoImg(g.away, "ts-logo")}</span>` +
    `<span class="ts-head-label">TEAM STATS</span>` +
    `<span class="ts-head-team">${logoImg(g.home, "ts-logo")}</span></div>`;

  let i = 0;
  Object.keys(rows).forEach((k) => {
    const r = rows[k]!;
    const av = statNum(r.a ?? ""), hv = statNum(r.h ?? "");
    const lower = LOWER_BETTER.test(r.label) || LOWER_BETTER.test(k);
    let aWin = false, hWin = false, aPct = 50;
    if (av != null && hv != null && av + hv > 0) {
      aPct = (av / (av + hv)) * 100;
      if (av !== hv) { aWin = lower ? av < hv : av > hv; hWin = !aWin; }
    }
    out += `<div class="ts-row${statsAnimate ? " rise-in" : ""}" style="--i:${i++}">` +
      `<div class="ts-vals"><span class="ts-val${aWin ? " win" : ""}"${aWin ? ` style="color:${ac}"` : ""}>${escapeHtml(r.a ?? "—")}</span>` +
      `<span class="ts-label">${escapeHtml(r.label)}</span>` +
      `<span class="ts-val${hWin ? " win" : ""}"${hWin ? ` style="color:${hc}"` : ""}>${escapeHtml(r.h ?? "—")}</span></div>` +
      `<div class="ts-bar"><span style="width:${aPct.toFixed(1)}%;background:${ac}"></span>` +
      `<span style="width:${(100 - aPct).toFixed(1)}%;background:${hc}"></span></div></div>`;
  });
  return out;
}

const LEADER_LABELS: Record<string, string> = {
  passingYards: "Passing", rushingYards: "Rushing", receivingYards: "Receiving",
  sacks: "Sacks", totalTackles: "Tackles", interceptions: "Interceptions",
};

function buildLeaderCards(g: NormGame): string {
  const L: any[] = lastSummary?.leaders || [];
  if (!L.length) return '<div class="bs-empty">No leaders yet</div>';
  const byCat = new Map<string, { away?: any; home?: any }>();
  L.forEach((side: any) => {
    const isHome = String(side?.team?.id) === g.home.id;
    (side?.leaders || []).forEach((cat: any) => {
      const top = cat?.leaders?.[0];
      if (!top) return;
      const key = String(cat.name || cat.displayName || "");
      const cur = byCat.get(key) || {};
      if (isHome) cur.home = top; else cur.away = top;
      byCat.set(key, cur);
    });
  });
  const ac = railColorOf(g.away, "#d50a0a"), hc = railColorOf(g.home, "#013369");
  let out = "";
  let i = 0;
  byCat.forEach((pair, key) => {
    const label = LEADER_LABELS[key] || String(key).replace(/([A-Z])/g, " $1").replace(/^./, (c) => c.toUpperCase());
    const row = (top: any, _team: NormTeam, color: string): string => {
      if (!top) return "";
      const ath = top.athlete || {};
      const head = ath.headshot?.href ? proxied(String(ath.headshot.href)) : "";
      return `<div class="ld-row" style="--tc:${color}">` +
        (head ? `<img class="ld-head" data-psrc="${escapeHtml(head)}" alt="">` : `<span class="ld-head ph"></span>`) +
        `<span class="ld-who"><span class="ld-name">${escapeHtml(ath.shortName || ath.displayName || "")}</span>` +
        `<span class="ld-stat">${escapeHtml(String(top.displayValue || ""))}</span></span></div>`;
    };
    out += `<div class="ld-card${statsAnimate ? " rise-in" : ""}" style="--i:${i++}">` +
      `<div class="ld-cat">${escapeHtml(label)}</div>` +
      row(pair.away, g.away, ac) + row(pair.home, g.home, hc) + `</div>`;
  });
  return `<div class="ld-grid">${out}</div>`;
}

function buildPlayerPanel(teamId: string): string {
  const bplayers: any[] = lastSummary?.boxscore?.players || [];
  const side = bplayers.find((p) => String(p?.team?.id) === teamId);
  if (!side) return '<div class="bs-empty">No player stats yet</div>';
  let out = "";
  (side.statistics || []).forEach((grp: any) => {
    const ath: any[] = grp?.athletes || [];
    if (!ath.length) return;
    const labels: string[] = grp.labels || [];
    out += `<div class="bs-section-hdr"><span class="bs-dot"></span>${escapeHtml(grp.text || grp.name || "")}</div>`;
    out += `<table class="bs-table"><thead><tr><th class="bs-th-player">Player</th>`;
    labels.forEach((l) => { out += `<th>${escapeHtml(l)}</th>`; });
    out += "</tr></thead><tbody>";
    ath.forEach((row: any) => {
      const nm = row?.athlete?.shortName || row?.athlete?.displayName || "";
      out += `<tr class="bs-row"><td class="bs-player"><div class="bs-pname">${escapeHtml(nm)}</div></td>`;
      (row?.stats || []).forEach((v: any) => { out += `<td>${escapeHtml(String(v))}</td>`; });
      out += "</tr>";
    });
    out += "</tbody></table>";
  });
  return out || '<div class="bs-empty">No player stats yet</div>';
}

// Segmented toggles must PERSIST across content re-renders — a toggle
// rebuilt by innerHTML is a brand-new element that starts at its new
// --seg-i, so the thumb has nothing to slide FROM. The Plays toggle lives
// in the shell and animated for free; Stats/Standings rebuilt themselves
// and jumped. This helper keeps one element and just updates its state.
// Content beneath a segmented toggle fades/rises in on every swap, so the
// switch reads as a transition rather than a hard cut.
function animateSegSwap(el: HTMLElement | null): void {
  if (!el) return;
  el.classList.remove("seg-swap");
  void el.offsetWidth; // reflow so the animation restarts
  el.classList.add("seg-swap");
}

function syncSegToggle(track: HTMLElement | null, activeIndex: number, attr: string, value: string): void {
  if (!track) return;
  track.style.setProperty("--seg-i", String(activeIndex));
  track.setAttribute("data-active", value);
  track.querySelectorAll<HTMLElement>(".plays-seg").forEach((seg) => {
    seg.classList.toggle("is-active", seg.getAttribute(attr) === value);
  });
}

function statsToggleHtml(): string {
  return `<div class="plays-toggle" id="stats-toggle" data-active="${statsView}" style="--seg-i:${statsView === "players" ? 1 : 0}">` +
    `<span class="plays-toggle-thumb"></span>` +
    `<button class="plays-seg${statsView === "team" ? " is-active" : ""}" data-stats="team" type="button">Team</button>` +
    `<button class="plays-seg${statsView === "players" ? " is-active" : ""}" data-stats="players" type="button">Players</button></div>`;
}

function renderStatsTab(): void {
  const g = lastGame;
  const root = $("tab-box");
  if (!g || !root) return;

  // Build (or keep) the toggle, then swap ONLY the body beneath it.
  let toggle = root.querySelector<HTMLElement>("#stats-toggle");
  let body = root.querySelector<HTMLElement>("#stats-body");
  if (!toggle || !body) {
    root.innerHTML = statsToggleHtml() + `<div id="stats-body"></div>`;
    toggle = root.querySelector<HTMLElement>("#stats-toggle");
    body = root.querySelector<HTMLElement>("#stats-body");
    root.querySelectorAll<HTMLElement>("#stats-toggle .plays-seg").forEach((seg) => {
      seg.addEventListener("click", () => {
        const v = seg.getAttribute("data-stats");
        if (v !== "team" && v !== "players") return;
        if (v === statsView) return;
        statsView = v;
        statsAnimate = true;
        // Slide the thumb NOW (the element survives), then re-render below.
        syncSegToggle(toggle, v === "players" ? 1 : 0, "data-stats", v);
        renderStatsTab();
      });
    });
  } else {
    syncSegToggle(toggle, statsView === "players" ? 1 : 0, "data-stats", statsView);
  }
  if (!body) return;

  let html = "";
  if (statsView === "team") {
    html = `<div class="ts-wrap">${buildTeamCompare(g)}</div>`;
  } else {
    html = buildLeaderCards(g);
    html += `<div class="bs-team-tabs">` +
      `<button class="bs-team-tab${statsBoxTeam === "away" ? " active" : ""}" data-bs-team="away" type="button">` +
      `<span class="bs-team-tab-logo">${logoImg(g.away, "bs-team-tab-logo")}</span></button>` +
      `<button class="bs-team-tab${statsBoxTeam === "home" ? " active" : ""}" data-bs-team="home" type="button">` +
      `<span class="bs-team-tab-logo">${logoImg(g.home, "bs-team-tab-logo")}</span></button></div>` +
      `<div class="bs-panel-wrap"><div class="bs-panel active">` +
      buildPlayerPanel(statsBoxTeam === "home" ? g.home.id : g.away.id) + `</div></div>`;
  }
  body.innerHTML = html;
  animateSegSwap(body);
  hydrateProxiedImages(body);
  statsAnimate = false; // consumed

  body.querySelectorAll<HTMLElement>(".bs-team-tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      const t = btn.dataset.bsTeam;
      if (t === "away" || t === "home") { statsBoxTeam = t; renderStatsTab(); }
    });
  });
}

let statsBoxTeam: "away" | "home" = "away";

// ── PLAYS tab (scoring | drives) + highlights ─────────────────────────────

const openDrives = new Set<string>();
let playsAnimate = false;

function driveTeamOf(d: any, g: NormGame): NormTeam | null {
  const id = d?.team?.id != null ? String(d.team.id) : "";
  return id === g.home.id ? g.home : id === g.away.id ? g.away : null;
}

// ── Play entries (ESPN drive-view anatomy) ────────────────────────────────
// rail + icon + "23 Yard Pass · 1st & 10 at DET 44" + "13:16 1st — text"

const PLAY_ICONS: Record<string, string> = {
  pass: '<path d="M3 12c3-5 15-5 18 0-3 5-15 5-18 0z"/><path d="M9 10.5l1.5 3M12 10l0 4M15 10.5l-1.5 3"/>',
  run: '<path d="M4 17h9M8 12h9M6 7h9"/><path d="M17 9l3 3-3 3"/>',
  sack: '<path d="M12 3l7 3v5c0 5-3.5 8-7 10-3.5-2-7-5-7-10V6z"/>',
  kick: '<path d="M6 18c6 0 12-6 12-12"/><path d="M15 3l3 3-3 3M4 20l2-2"/>',
  int: '<path d="M4 7h10l3 3M4 17h10l3-3"/><path d="M14 4l3 3-3 3M14 20l3-3-3-3"/>',
  flag: '<path d="M6 21V4"/><path d="M6 4h11l-2.5 3.5L17 11H6"/>',
  dot: '<circle cx="12" cy="12" r="3"/>',
};

function playIconKey(t: string): string {
  const s = t.toLowerCase();
  if (/interception/.test(s)) return "int";
  if (/sack/.test(s)) return "sack";
  if (/punt|kick|field goal|extra point/.test(s)) return "kick";
  if (/pass|reception|incompletion/.test(s)) return "pass";
  if (/rush|run/.test(s)) return "run";
  if (/penalty/.test(s)) return "flag";
  return "dot";
}
function playIcon(t: string): string {
  return `<svg class="dp-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${PLAY_ICONS[playIconKey(t)]}</svg>`;
}

const PERIOD_LC = ["", "1st", "2nd", "3rd", "4th"];
function periodLc(n: number): string {
  if (n <= 0) return "";
  return PERIOD_LC[n] || "OT" + (n > 5 ? String(n - 4) : "");
}

function playTitle(p: any): string {
  const t = playTypeText(p);
  const y = Number(p?.statYardage) || 0;
  const text = String(p?.text || "");
  if (/kickoff/i.test(t)) {
    const m = text.match(/from ([A-Z]{2,4} \d{1,2})/);
    return "Kickoff" + (m ? ` from ${m[1]}` : "");
  }
  if (/interception/i.test(t)) return "Interception";
  if (/punt/i.test(t)) return "Punt";
  if (/field goal|extra point/i.test(t)) return t;
  if (/penalty/i.test(t)) return "Penalty";
  if (/sack/i.test(t)) return `${y} Yard Sack`;
  if (/incompletion/i.test(t)) return "Incomplete Pass";
  if (/pass|reception/i.test(t)) return `${y} Yard Pass`;
  if (/rush|run/i.test(t)) return `${y} Yard Run`;
  return t || "Play";
}

function playEntryHtml(p: any, color: string): string {
  const title = playTitle(p);
  const dd = String(p?.start?.downDistanceText || "");
  let text = String(p?.text || "").trim();
  let boldSuffix = "";
  const form = text.match(/^\((.*?)\)\s*/);
  if (form) { boldSuffix = " " + form[1]; text = text.slice(form[0].length); }
  const clk = `${p?.clock?.displayValue || ""} ${periodLc(Number(p?.period?.number) || 0)}`.trim();
  return `<div class="dp-entry" style="--rail:${color}">` +
    `<div class="dp-title">${playIcon(playTypeText(p))}<b>${escapeHtml(title)}</b>` +
    (dd ? `<span class="dp-dd"> · ${escapeHtml(dd)}</span>` : "") + `</div>` +
    `<div class="dp-body"><b>${escapeHtml(clk)}${escapeHtml(boldSuffix)}</b>` +
    `${clk || boldSuffix ? " — " : ""}${escapeHtml(text)}</div></div>`;
}

function ordinalQuarter(period: number): string {
  if (period >= 5) return period === 5 ? "OVERTIME" : `${period - 4}OT`;
  const ord = ["", "1ST", "2ND", "3RD", "4TH"][period] || `${period}TH`;
  return `${ord} QUARTER`;
}

// playId -> containing drive, for the "7 plays, 79 yards, 3:48" line.
function driveOfPlay(playId: string): any | null {
  const s = lastSummary || {};
  const all: any[] = [...(s.drives?.previous || [])];
  if (s.drives?.current) all.push(s.drives.current);
  for (const d of all) {
    if ((d?.plays || []).some((p: any) => String(p?.id) === playId)) return d;
  }
  return null;
}

// ESPN-style scoring cards (Joe's ref): quarter section headers, then per
// play: logo | bold type + clock | away/home running-score columns with the
// SCORING team's total emphasized; description; drive summary line.
function buildScoringCards(_compact: boolean): string {
  const g = lastGame;
  const sp: any[] = lastSummary?.scoringPlays || [];
  if (!g || !sp.length) return '<div class="plays-empty">No scoring plays yet</div>';
  let html = "";
  let lastPeriod = -1;
  let i = 0;
  for (const p of sp) {
    const period = Number(p?.period?.number ?? p?.period) || 0;
    if (period !== lastPeriod) {
      html += `<div class="sc-qtr${playsAnimate ? " rise-in" : ""}" style="--i:${i}">${escapeHtml(ordinalQuarter(period))}</div>`;
      lastPeriod = period;
      i++;
    }
    const teamId = p?.team?.id != null ? String(p.team.id) : "";
    const isHome = teamId === g.home.id;
    const team = isHome ? g.home : g.away;
    const color = railColorOf(team, isHome ? "#013369" : "#d50a0a");
    const typeName = String(p?.scoringType?.displayName || p?.type?.text || "Score");
    const clock = `${escapeHtml(String(p?.clock?.displayValue || ""))} - ${escapeHtml(String(period <= 4 ? ["","1st","2nd","3rd","4th"][period] : "OT"))}`;
    const away = Number(p?.awayScore) || 0, home = Number(p?.homeScore) || 0;
    const drive = driveOfPlay(String(p?.id));
    const dPlays = drive ? realPlayCount(drive) : 0;
    const dYards = drive?.yards;
    const dTime = drive?.timeElapsed?.displayValue;
    const driveLine = drive && (dPlays || dYards != null)
      ? `<div class="sc-drive">${dPlays} plays${dYards != null ? `, ${escapeHtml(String(dYards))} yards` : ""}${dTime ? `, ${escapeHtml(String(dTime))}` : ""}</div>`
      : "";
    html += `<div class="sc-card${playsAnimate ? " rise-in" : ""}" style="--i:${i};--tc:${color}">` +
      `<div class="sc-top">` +
        logoImg(team, "sc-logo") +
        `<div class="sc-title-wrap"><div class="sc-type">${escapeHtml(typeName)}</div><div class="sc-clock">${clock}</div></div>` +
        `<div class="sc-scores">` +
          `<div class="sc-col${!isHome ? " sc-col-scored" : ""}"><span class="sc-num">${away}</span><span class="sc-abbr">${escapeHtml(g.away.abbr)}</span></div>` +
          `<div class="sc-col${isHome ? " sc-col-scored" : ""}"><span class="sc-num">${home}</span><span class="sc-abbr">${escapeHtml(g.home.abbr)}</span></div>` +
        `</div>` +
      `</div>` +
      `<div class="sc-desc">${escapeHtml(String(p?.text || ""))}</div>` +
      driveLine +
      `</div>`;
    i++;
  }
  return html;
}

function driveScores(d: any): { away: number; home: number } | null {
  const plays: any[] = d?.plays || [];
  for (let i = plays.length - 1; i >= 0; i--) {
    const p = plays[i];
    if (p?.awayScore != null || p?.homeScore != null) {
      return { away: Number(p.awayScore) || 0, home: Number(p.homeScore) || 0 };
    }
  }
  return null;
}

function buildDriveCards(g: NormGame): string {
  const s = lastSummary || {};
  const list: Array<{ d: any; current: boolean; key: string }> = [];
  if (s.drives?.current) list.push({ d: s.drives.current, current: true, key: "cur" });
  const prev: any[] = s.drives?.previous || [];
  for (let i = prev.length - 1; i >= 0; i--) list.push({ d: prev[i], current: false, key: "d" + i });
  if (!list.length) return '<div class="plays-empty">No drives yet</div>';

  return list.map((w, idx) => {
    const d = w.d;
    const team = driveTeamOf(d, g);
    const color = team ? railColorOf(team, team.id === g.home.id ? "#013369" : "#d50a0a") : "var(--text-muted)";
    const result = String(d?.displayResult || d?.result || (w.current ? "In Progress" : ""));
    const stat = (label: string, val: string): string =>
      `<span class="dv-stat"><span class="dv-stat-k">${label}</span><span class="dv-stat-v">${escapeHtml(val)}</span></span>`;
    const sc = driveScores(d);
    const open = openDrives.has(w.key);
    const plays: any[] = displayPlaysOf(d);
    const body = plays.length
      ? `<div class="drive-body"><div class="dp-list">${plays.map((p) => playEntryHtml(p, color)).join("")}</div></div>`
      : "";
    return `<button type="button" class="drive-card${w.current ? " current" : ""}${open ? " open" : ""}` +
      `${playsAnimate ? " rise-in" : ""}" data-drive="${w.key}" style="--i:${idx}">` +
      `<div class="drive-head">` +
      (team ? logoImg(team, "drive-logo") : "") +
      `<span class="dv-result">${escapeHtml(result)}</span>` +
      stat("PLAYS", String(realPlayCount(d))) +
      stat("YDS", String(d?.yards ?? "—")) +
      stat("TTL TIME", String(d?.timeElapsed?.displayValue || "—")) +
      (sc ? `<span class="dv-score">` +
        `<span class="dv-score-t">${logoImg(g.away, "dv-score-logo")}<b>${sc.away}</b></span>` +
        `<span class="dv-score-t">${logoImg(g.home, "dv-score-logo")}<b>${sc.home}</b></span></span>` : "") +
      `<svg class="drive-chev" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="M6 9l6 6 6-6"/></svg>` +
      `</div>${body}</button>`;
  }).join("");
}

function renderPlaysTab(): void {
  const g = lastGame;
  if (!g) return;
  const scoring = $("scoring-plays-list");
  const drives = $("all-plays-list");
  if (scoring) scoring.innerHTML = buildScoringCards(false);
  if (drives) {
    drives.innerHTML = buildDriveCards(g);
    drives.querySelectorAll<HTMLElement>(".drive-card[data-drive]").forEach((card) => {
      card.addEventListener("click", () => {
        const key = card.getAttribute("data-drive");
        if (!key) return;
        if (openDrives.has(key)) openDrives.delete(key); else openDrives.add(key);
        card.classList.toggle("open");
        syncPagerAfterAnimation();
      });
    });
  }
  playsAnimate = false;
  void loadClipsInto("plays-clips");
}

function setPlaysView(which: "scoring" | "all"): void {
  const toggle = $("plays-toggle");
  const scoringList = $("scoring-plays-list");
  const allList = $("all-plays-list");
  if (!toggle || !scoringList || !allList) return;
  toggle.setAttribute("data-active", which);
  toggle.querySelectorAll<HTMLElement>(".plays-seg").forEach((seg) => {
    seg.classList.toggle("is-active", seg.getAttribute("data-plays") === which);
    const track = seg.closest<HTMLElement>(".plays-toggle");
    if (track) track.style.setProperty("--seg-i", which === "all" ? "1" : "0");
    if (track) track.setAttribute("data-active", which);
  });
  const show = which === "all" ? allList : scoringList;
  const hide = which === "all" ? scoringList : allList;
  (hide as HTMLElement).hidden = true;
  (show as HTMLElement).hidden = false;
  show.classList.remove("plays-list-enter");
  void (show as HTMLElement).offsetWidth;
  show.classList.add("plays-list-enter");
}

function setupPlaysToggle(): void {
  const toggle = $("plays-toggle");
  if (!toggle) return;
  toggle.querySelectorAll<HTMLElement>(".plays-seg").forEach((seg) => {
    seg.addEventListener("click", () => {
      const which = seg.getAttribute("data-plays");
      if (which === "scoring" || which === "all") setPlaysView(which);
    });
  });
}

// Highlights — /api/clips returns {clips:[{headline,thumbnail,url,...}]};
// ESPN clips aren't play-keyed, so this is a rail, not per-play buttons.
let clipsCache: any[] | null = null;
let clipsCacheTs = 0;

async function loadClipsInto(containerId: string): Promise<void> {
  const el = $(containerId);
  if (!el || eventId == null) return;
  const now = Date.now();
  if (!clipsCache || now - clipsCacheTs > 60000) {
    try {
      const res = await fetch(`/api/clips/${eventId}`);
      if (res.ok) {
        const data: any = await res.json();
        clipsCache = data?.clips || [];
        clipsCacheTs = now;
      }
    } catch (e) { reportError("loadClips", e); }
  }
  const clips = clipsCache || [];
  if (!clips.length) { el.innerHTML = ""; return; }
  el.className = "clips-grid";
  el.innerHTML = clips.slice(0, 8).map((c: any) =>
    `<button class="clip-card" type="button" data-url="${escapeHtml(String(c.url || ""))}">` +
    // Every card gets the same 16/9 media panel: real thumb when we have
    // one, play-glyph placeholder when we don't — uniform grid either way.
    `<div class="clip-media">` +
      (c.thumbnail ? `<img data-psrc="${escapeHtml(proxied(String(c.thumbnail)))}" alt="">` : "") +
      `<span class="clip-play">▶</span>` +
    `</div>` +
    `<div class="chead">${escapeHtml(String(c.headline || "Highlight"))}</div></button>`
  ).join("");
  // THE missing line — this grid was never hydrated, so data-psrc thumbs
  // stayed src-less grey boxes forever (stats and wrap always had this call).
  hydrateProxiedImages(el);
  el.querySelectorAll<HTMLElement>(".clip-card[data-url]").forEach((card) => {
    card.addEventListener("click", () => {
      const url = card.getAttribute("data-url");
      if (!url) return;
      try { navigateTo(url); } catch (e) { reportError("navigateTo(clip)", e); }
    });
  });
}

// ── WIN PROB (MLB chart structure, NFL data) ──────────────────────────────
// /api/winprob returns {winprobability:[{homeWinPercentage 0..1, playId}]}.
// Quarter gridlines come from a playId -> period map built from drives.

let winProbCache: any[] | null = null;

async function fetchWinProb(): Promise<any[] | null> {
  if (!eventId) return null;
  try {
    const res = await fetch(`/api/winprob/${eventId}`);
    if (!res.ok) return winProbCache;
    const data: any = await res.json();
    const arr = Array.isArray(data) ? data : data?.winprobability;
    if (Array.isArray(arr)) { winProbCache = arr; return arr; }
    return winProbCache;
  } catch (e) {
    reportError("fetchWinProb", e);
    return winProbCache;
  }
}

function buildPlayIndex(): Map<string, { period: number; text: string }> {
  const map = new Map<string, { period: number; text: string }>();
  const add = (plays: any[]): void => {
    for (const p of plays) {
      if (p?.id != null) map.set(String(p.id), {
        period: Number(p?.period?.number) || 0,
        text: String(p?.text || ""),
      });
    }
  };
  const prev: any[] = lastSummary?.drives?.previous || [];
  prev.forEach((d) => add(d?.plays || []));
  if (lastSummary?.drives?.current) add(lastSummary.drives.current.plays || []);
  return map;
}

let wpAnimate = false;

async function renderWinProb(): Promise<void> {
  try { await renderWinProbInner(); } finally { wpAnimate = false; }
}

async function renderWinProbInner(): Promise<void> {
  const container = $("tab-winprob");
  if (!container) return;
  const g = lastGame;
  if (!g) {
    container.innerHTML = '<div class="plays-empty">Waiting for game data…</div>';
    return;
  }
  if (!container.querySelector(".wp-summary")) {
    container.innerHTML = '<div class="plays-empty">Loading win probability…</div>';
  }
  const wpRaw = await fetchWinProb();
  if (!wpRaw || !wpRaw.length) {
    container.innerHTML = '<div class="plays-empty">Win probability not available yet</div>';
    return;
  }

  const playIdx = buildPlayIndex();
  const awayColor = g.away.color || "#d50a0a";
  const homeColor = g.home.color || "#013369";
  const latest = wpRaw[wpRaw.length - 1];
  const homeProbNow = Math.round((Number(latest?.homeWinPercentage) || 0.5) * 100);
  const awayProbNow = 100 - homeProbNow;

  const W = 520, H = 125;
  const PL = 36, PR = 16, PT = 10, PB = 22;
  const CW = W - PL - PR, CH = H - PT - PB;
  const stepX = CW / Math.max(1, wpRaw.length - 1);
  const midY = PT + CH / 2;

  const pts = wpRaw.map((d: any, i: number) => {
    const hp = (Number(d?.homeWinPercentage) || 0.5) * 100;
    const info = d?.playId != null ? playIdx.get(String(d.playId)) : undefined;
    return {
      x: PL + i * stepX,
      y: PT + CH / 2 + ((hp - 50) / 50) * (CH / 2),
      homeProb: hp,
      awayProb: 100 - hp,
      text: info?.text || "",
      period: info?.period || 0,
    };
  });

  const linePoints = pts.map((p) => `${p.x},${p.y}`).join(" ");
  const polyPts = [`${PL},${midY}`, ...pts.map((p) => `${p.x},${p.y}`), `${PL + CW},${midY}`].join(" ");

  const light = document.documentElement.getAttribute("data-theme") === "light";
  // Team-filled areas need a separator from the chart background: a navy
  // team's fill vanishes into dark mode, and a white/silver team washes out
  // in light mode (Joe). White outline on dark, navy on light.
  const areaEdge = light ? "rgba(10,24,40,0.55)" : "rgba(255,255,255,0.85)";
  const ink = light
    ? { mid: "rgba(10,24,40,0.30)", strong: "rgba(10,24,40,0.62)", label: "rgba(10,24,40,0.50)", grid: "rgba(10,24,40,0.10)", chartBg: "rgba(10,24,40,0.05)", dotFill: "#0a1828", dotRing: "rgba(10,24,40,0.6)" }
    : { mid: "rgba(255,255,255,0.30)", strong: "rgba(255,255,255,0.55)", label: "rgba(255,255,255,0.45)", grid: "rgba(255,255,255,0.08)", chartBg: "rgba(255,255,255,0.04)", dotFill: "#fff", dotRing: "rgba(255,255,255,0.6)" };

  let quarterLines = "";
  let lastQ = 0;
  pts.forEach((p) => {
    if (p.period && p.period !== lastQ) {
      lastQ = p.period;
      if (p.period > 1) {
        quarterLines += `<line x1="${p.x}" y1="${PT}" x2="${p.x}" y2="${PT + CH}" stroke="${ink.grid}" stroke-width="1" stroke-dasharray="3,3"/>`;
      }
      quarterLines += `<text x="${p.x + 3}" y="${PT + CH + 15}" font-size="8" fill="${ink.strong}" font-family="monospace">${periodLabel(p.period)}</text>`;
    }
  });

  const zones = pts.map((p, i) => {
    const prev = pts[i - 1];
    const next = pts[i + 1];
    const x = i === 0 ? PL : (prev ? prev.x + (p.x - prev.x) / 2 : PL);
    const nx = i === pts.length - 1 ? PL + CW : (next ? p.x + (next.x - p.x) / 2 : PL + CW);
    const per = p.period ? periodLabel(p.period) : "";
    return `<rect x="${x}" y="${PT}" width="${nx - x}" height="${CH}" class="wp-zone"
      data-x="${p.x}" data-y="${p.y}"
      data-home="${p.homeProb.toFixed(1)}" data-away="${p.awayProb.toFixed(1)}"
      data-desc="${escapeHtml(p.text)}" data-inn="${per}"/>`;
  }).join("");

  container.innerHTML = `
    <div class="wp-summary">
      <div class="wp-team wp-team-away">
        <span class="wp-team-logo">${logoHtml(g.away, "wp-team-logo")}</span>
        <span class="wp-team-pct" style="color:${awayColor}">${awayProbNow}%</span>
      </div>
      <div class="wp-title">WIN PROBABILITY</div>
      <div class="wp-team wp-team-home">
        <span class="wp-team-pct" style="color:${homeColor}">${homeProbNow}%</span>
        <span class="wp-team-logo">${logoHtml(g.home, "wp-team-logo")}</span>
      </div>
    </div>

    <div class="wp-prob-bar">
      <div class="wp-prob-bar-fill" style="width:${awayProbNow}%;background:${awayColor};"></div>
      <div class="wp-prob-bar-fill wp-prob-bar-home" style="width:${homeProbNow}%;background:${homeColor};"></div>
    </div>

    <div class="wp-chart-wrap">
      <div class="wp-tooltip" id="wp-tooltip"></div>
      <svg class="wp-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet">
        <rect x="${PL}" y="${PT}" width="${CW}" height="${CH}" fill="${ink.chartBg}" rx="2"/>
        <defs>
          <clipPath id="wp-clip-top"><rect x="${PL}" y="${PT}" width="${CW}" height="${CH / 2}"/></clipPath>
          <clipPath id="wp-clip-bot"><rect x="${PL}" y="${PT + CH / 2}" width="${CW}" height="${CH / 2}"/></clipPath>
        </defs>
        <polygon points="${polyPts}" fill="${awayColor}" opacity="0.9" clip-path="url(#wp-clip-top)" stroke="${areaEdge}" stroke-width="0.9" stroke-linejoin="round"/>
        <polygon points="${polyPts}" fill="${homeColor}" opacity="0.9" clip-path="url(#wp-clip-bot)" stroke="${areaEdge}" stroke-width="0.9" stroke-linejoin="round"/>
        <line x1="${PL}" y1="${midY}" x2="${PL + CW}" y2="${midY}" stroke="${ink.mid}" stroke-width="1" stroke-dasharray="4,3"/>
        <text x="${PL - 4}" y="${midY + 3}" text-anchor="end" font-size="8" fill="${ink.strong}" font-family="monospace">50%</text>
        <text x="${PL - 4}" y="${PT + 6}" text-anchor="end" font-size="8" fill="${awayColor}" font-family="monospace">${escapeHtml(g.away.abbr)}</text>
        <text x="${PL - 4}" y="${PT + CH + 2}" text-anchor="end" font-size="8" fill="${homeColor}" font-family="monospace">${escapeHtml(g.home.abbr)}</text>
        ${quarterLines}
        <polyline class="wp-line${wpAnimate ? " wp-draw" : ""}" pathLength="1" points="${linePoints}" fill="none" stroke="${ink.strong}" stroke-width="1.2" stroke-linejoin="round"/>
        ${zones}
        <circle id="wp-dot" cx="0" cy="0" r="4" fill="${ink.dotFill}" stroke="${ink.dotRing}" stroke-width="2" style="display:none;pointer-events:none;"/>
        <text x="${PL + CW / 2}" y="${H - 2}" text-anchor="middle" font-size="9" fill="${ink.label}" font-family="monospace">QUARTER</text>
      </svg>
    </div>

    <div class="wp-legend">
      <div class="wp-legend-item"><span class="wp-legend-swatch" style="background:${awayColor}"></span>${escapeHtml(g.away.name)}</div>
      <div class="wp-legend-item"><span class="wp-legend-swatch" style="background:${homeColor}"></span>${escapeHtml(g.home.name)}</div>
    </div>
  `;

  wireWinProbHover(g.away.abbr, g.home.abbr, awayColor, homeColor);
}

function wireWinProbHover(awayAbbr: string, homeAbbr: string, awayColor: string, homeColor: string): void {
  const chart = document.querySelector(".wp-chart") as SVGElement | null;
  const tooltip = $("wp-tooltip");
  const dot = document.getElementById("wp-dot");
  if (!chart || !tooltip || !dot) return;

  const showFor = (z: SVGElement): void => {
    const ds = (z as unknown as HTMLElement).dataset;
    dot.setAttribute("cx", ds.x || "0");
    dot.setAttribute("cy", ds.y || "0");
    (dot as unknown as HTMLElement).style.display = "block";
    tooltip.innerHTML = `
      ${ds.inn ? `<div class="wp-tt-inn">${ds.inn}</div>` : ""}
      ${ds.desc ? `<div class="wp-tt-desc">${ds.desc}</div>` : ""}
      <div class="wp-tt-probs"><span style="color:${awayColor}">${awayAbbr} ${ds.away}%</span><span style="color:${homeColor}">${homeAbbr} ${ds.home}%</span></div>`;
    tooltip.style.display = "block";
  };

  const hide = (): void => {
    tooltip.style.display = "none";
    (dot as unknown as HTMLElement).style.display = "none";
  };

  chart.querySelectorAll(".wp-zone").forEach((zone) => {
    const z = zone as SVGElement;
    z.addEventListener("mouseenter", () => showFor(z));
    z.addEventListener("mouseleave", hide);
    z.addEventListener("click", (e: Event) => {
      e.stopPropagation();
      showFor(z);
    });
  });
}

function setupWinProbDismiss(): void {
  document.addEventListener("click", (e: MouseEvent) => {
    const tip = document.getElementById("wp-tooltip");
    if (!tip || tip.style.display === "none") return;
    const target = e.target as Element | null;
    if (target?.closest(".wp-chart")) return;
    tip.style.display = "none";
    const dotEl = document.getElementById("wp-dot");
    if (dotEl) (dotEl as unknown as HTMLElement).style.display = "none";
  });
}

// ── STANDINGS (AFC / NFC divisions) ───────────────────────────────────────
// VERIFY on first live render: /api/standings shape is unseen. The walker
// collects any node with standings.entries[] at any depth and reads stats
// by name with abbreviation fallbacks.

let standCache: any = null;
let standCacheTs = 0;
let standActiveLeague = "AFC";

async function fetchStandingsData(): Promise<any> {
  const now = Date.now();
  if (standCache && now - standCacheTs < 120000) return standCache;
  const res = await fetch("/api/standings");
  if (!res.ok) throw new Error("standings fetch failed");
  const data = await res.json();
  standCache = data; standCacheTs = now;
  return data;
}

interface StandGroup { name: string; entries: any[]; }

function collectGroups(root: any): StandGroup[] {
  const groups: StandGroup[] = [];
  const walk = (node: any): void => {
    if (!node || typeof node !== "object") return;
    const entries = node.standings?.entries;
    if (Array.isArray(entries) && entries.length) {
      groups.push({ name: String(node.name || node.abbreviation || ""), entries });
    }
    (node.children || []).forEach(walk);
  };
  walk(root);
  return groups;
}

function statOf(entry: any, names: string[]): string {
  const stats: any[] = entry?.stats || [];
  for (const s of stats) {
    if (names.indexOf(s?.name) >= 0 || names.indexOf(s?.abbreviation) >= 0) {
      return s.displayValue != null ? String(s.displayValue) : String(s.value ?? "");
    }
  }
  return "—";
}

const NFL_DIVISIONS: Record<string, string> = {
  // AFC East / North / South / West
  "2": "AFC East", "15": "AFC East", "17": "AFC East", "20": "AFC East",
  "33": "AFC North", "4": "AFC North", "5": "AFC North", "23": "AFC North",
  "34": "AFC South", "11": "AFC South", "30": "AFC South", "10": "AFC South",
  "7": "AFC West", "12": "AFC West", "13": "AFC West", "24": "AFC West",
  // NFC East / North / South / West
  "6": "NFC East", "19": "NFC East", "21": "NFC East", "28": "NFC East",
  "3": "NFC North", "8": "NFC North", "9": "NFC North", "16": "NFC North",
  "1": "NFC South", "29": "NFC South", "18": "NFC South", "27": "NFC South",
  "22": "NFC West", "14": "NFC West", "25": "NFC West", "26": "NFC West",
};
const DIV_ORDER = ["East", "North", "South", "West"];

let standView: "standings" | "bracket" = "standings";

function bracketSlot(label: string): string {
  return `<div class="bk-slot"><span class="bk-seed">${escapeHtml(label)}</span><span class="bk-box"></span></div>`;
}
function bracketPair(a: string, b: string): string {
  return `<div class="bk-pair">${bracketSlot(a)}${bracketSlot(b)}</div>`;
}
// Empty playoff bracket for one conference (seeds fill in as the regular
// season sorts itself out). The Super Bowl column shows on BOTH conferences.
function buildBracketHtml(conf: string): string {
  const col = (title: string, inner: string): string =>
    `<div class="bk-col"><div class="bk-col-hdr">${escapeHtml(title)}</div>${inner}</div>`;
  return `<div class="bracket-scroll"><div class="bracket">` +
    col("WILD CARD", bracketPair("2", "7") + bracketPair("3", "6") + bracketPair("4", "5")) +
    col("DIVISIONAL", bracketPair("1", "—") + bracketPair("—", "—")) +
    col(`${escapeHtml(conf)} CHAMP`, bracketPair("—", "—")) +
    col("SUPER BOWL", `<div class="bk-pair bk-final">${bracketSlot("AFC")}${bracketSlot("NFC")}</div>`) +
    `</div></div>`;
}

async function loadStandingsView(): Promise<void> {
  const body = $("stand-body");
  if (!body) return;
  // Mount the toggle ONCE so its thumb can slide between views (a rebuilt
  // toggle has no previous position to animate from); only #stand-body swaps.
  let vt = body.querySelector<HTMLElement>(".stand-view-toggle");
  let sbody = body.querySelector<HTMLElement>("#stand-body");
  if (!vt || !sbody) {
    body.innerHTML = `<div class="plays-toggle stand-view-toggle" style="--seg-i:${standView === "bracket" ? 1 : 0}">` +
      `<span class="plays-toggle-thumb"></span>` +
      `<button class="plays-seg${standView === "standings" ? " is-active" : ""}" data-sv="standings" type="button">Standings</button>` +
      `<button class="plays-seg${standView === "bracket" ? " is-active" : ""}" data-sv="bracket" type="button">Bracket</button></div>` +
      `<div id="stand-body"><div class="stand-msg">Loading…</div></div>`;
    vt = body.querySelector<HTMLElement>(".stand-view-toggle");
    sbody = body.querySelector<HTMLElement>("#stand-body");
    vt?.querySelectorAll<HTMLElement>(".plays-seg").forEach((s) => {
      s.addEventListener("click", () => {
        const v = s.getAttribute("data-sv");
        if (v !== "standings" && v !== "bracket") return;
        if (v === standView) return;
        standView = v;
        syncSegToggle(vt, v === "bracket" ? 1 : 0, "data-sv", v);
        void loadStandingsView();
      });
    });
  } else {
    syncSegToggle(vt, standView === "bracket" ? 1 : 0, "data-sv", standView);
  }
  if (!sbody) return;
  const seg = ""; // toggle is persistent now; content-only below
  try {

    if (standView === "bracket") {
      sbody.innerHTML = seg + buildBracketHtml(standActiveLeague);
      animateSegSwap(sbody);
    } else {
      const data = await fetchStandingsData();
      const groups = collectGroups(data).filter((grp) =>
        grp.name.toUpperCase().includes(standActiveLeague) ||
        grp.name.toUpperCase().includes(standActiveLeague === "AFC" ? "AMERICAN" : "NATIONAL"));
      const use = groups.length ? groups : collectGroups(data);
      if (!use.length) { body.innerHTML = seg + '<div class="stand-msg">No standings available.</div>'; }
      else {
        // Regroup the conference into its four DIVISIONS (static id map — the
        // payload's grouping is conference-level).
        const entries: any[] = use.flatMap((grp) => grp.entries);
        const byDiv = new Map<string, any[]>();
        entries.forEach((e: any) => {
          const id = String(e?.team?.id ?? "");
          const div = NFL_DIVISIONS[id] || "";
          if (!div.startsWith(standActiveLeague)) return;
          const list = byDiv.get(div) || [];
          list.push(e);
          byDiv.set(div, list);
        });
        const cards = DIV_ORDER.map((d) => {
          const name = `${standActiveLeague} ${d}`;
          const list = byDiv.get(name) || [];
          if (!list.length) return "";
          const rows = list.map((e: any, i: number) => {
            const t = e?.team || {};
            const team: NormTeam = {
              id: String(t.id ?? ""), abbr: String(t.abbreviation || "").toUpperCase(),
              name: String(t.displayName || ""), nick: String(t.name || ""),
              record: "", score: 0, color: "", logo: "",
            } as NormTeam;
            return `<div class="stand-row${i === 0 ? " leader" : ""}">` +
              `<span class="stand-pos${i === 0 ? " first" : ""}">${i + 1}</span>` +
              `<span class="stand-team">${logoImg(team, "stand-logo")}<span class="stand-abbr">${escapeHtml(team.abbr.slice(0, 4))}</span></span>` +
              `<span class="stand-stat">${escapeHtml(statOf(e, ["wins", "W"]))}</span>` +
              `<span class="stand-stat">${escapeHtml(statOf(e, ["losses", "L"]))}</span>` +
              `<span class="stand-stat muted">${escapeHtml(statOf(e, ["ties", "T"]))}</span>` +
              `<span class="stand-pct"><span class="stand-pct-val">${escapeHtml(statOf(e, ["winPercent", "PCT"]))}</span></span>` +
              `</div>`;
          }).join("");
          return `<div class="stand-card"><div class="stand-card-hdr"><span class="stand-card-dot"></span>` +
            `<span class="stand-card-name">${escapeHtml(name)}</span></div>` +
            `<div class="stand-col-hdr"><span>#</span><span class="stand-col-team">Team</span><span>W</span><span>L</span><span>T</span><span class="stand-col-pct">PCT</span></div>` +
            rows + `</div>`;
        }).join("");
        sbody.innerHTML = seg + (cards || '<div class="stand-msg">No standings available.</div>');
        animateSegSwap(sbody);
      }
    }
  } catch (e) {
    reportError("loadStandingsView", e);
    sbody.innerHTML = '<div class="stand-msg">Could not load standings.</div>';
  }
}

function setStandLeague(lg: string): void {
  standActiveLeague = lg;
  const nav = $("stand-nav");
  if (nav) {
    nav.setAttribute("data-active", lg);
    nav.querySelectorAll<HTMLElement>(".stand-seg").forEach((s) =>
      s.classList.toggle("is-active", s.getAttribute("data-league") === lg));
  }
  void loadStandingsView();
}

function setupStandings(): void {
  const nav = $("stand-nav");
  if (!nav) return;
  nav.querySelectorAll<HTMLElement>(".stand-seg").forEach((seg) => {
    seg.addEventListener("click", () => {
      const lg = seg.getAttribute("data-league");
      if (lg) setStandLeague(lg);
    });
  });
}

// ── Header + master render ────────────────────────────────────────────────

// Everything that can actually change between polls. If this string is
// identical we skip the render entirely — that redundant innerHTML rebuild
// (and the image re-hydration behind it) was the "blink" (same fix as MLB).
function payloadSignature(s: any): string {
  const c = s?.header?.competitions?.[0] || {};
  const st = c?.status || {};
  const comps: any[] = c?.competitors || [];
  const drives = s?.drives;
  const cur = drives?.current;
  const curPlays: any[] = cur?.plays || [];
  const lastPlay = curPlays[curPlays.length - 1];
  return [
    st?.type?.name, st?.period, st?.displayClock,
    comps.map((x: any) => `${x?.id}:${x?.score}`).join(","),
    (drives?.previous || []).length, curPlays.length,
    lastPlay?.id, cur?.yards, cur?.team?.id,
    (s?.scoringPlays || []).length,
    (s?.videos || []).length,
    (s?.winprobability || []).length,
    (s?.injuries || []).reduce((n: number, gp: any) => n + (gp?.injuries || []).length, 0),
    (s?.pickcenter || [])[0]?.details,
  ].join("|");
}

function render(summary: any): void {
  // Nothing moved since the last paint → leave the DOM alone. (Tab switches
  // and other user actions call their renderers directly, so they still work.)
  const sig = payloadSignature(summary);
  const unchanged = sig === lastRenderSig && !firstRender;
  lastSummary = summary;
  if (unchanged) return;
  lastRenderSig = sig;
  firstRender = false;
  const g = normalize(summary);
  if (!g) { reportError("normalize", "unreadable summary"); return; }
  lastGame = g;

  // postType override, mirroring MLB's lagging-feed guard.
  const isPostponed = postType === "postponed" || isPostponedName(g.statusName);
  const phase: Phase = isPostponed ? "post" : g.phase;

  document.body.classList.toggle("is-pregame", phase === "pre");
  document.body.classList.toggle("is-live", phase === "in");
  document.body.classList.toggle("is-final", phase === "post");

  void maybeNotifyPostgame(g);

  const loading = $("loading-state");
  const content = $("scorebug-content");
  if (loading) loading.style.display = "none";
  if (content) content.style.display = "";

  // meta strip
  const venueEl = $("venue-info");
  if (venueEl) {
    const venueName = String(g.venue?.fullName || "");
    let when = "";
    try {
      const dt = new Date(g.date);
      when = dt.toLocaleDateString("en-US", { month: "short", day: "numeric" }).toUpperCase() + " · " + formatGameTime(g.date);
    } catch { /* ignore */ }
    venueEl.textContent = [venueName.toUpperCase(), when].filter(Boolean).join(" · ");
  }
  const ctxEl = $("game-context");
  if (ctxEl) ctxEl.textContent = gameContextLabel(g);

  // score row
  setLogoHolder("away-logo-holder", g.away, "team-logo");
  setLogoHolder("home-logo-holder", g.home, "team-logo");
  const an = $("away-name"), hn = $("home-name");
  if (an) an.textContent = g.away.name;
  if (hn) hn.textContent = g.home.name;
  const ar = $("away-record"), hr = $("home-record");
  if (ar) ar.textContent = g.away.record;
  if (hr) hr.textContent = g.home.record;
  // Timeouts: live only — they're meaningless pregame and spent at final.
  const atoEl = $("away-timeouts"), htoEl = $("home-timeouts");
  const tos = phase === "in" ? timeoutsRemaining(summary, g) : null;
  if (atoEl && htoEl) {
    if (tos) {
      const total = (Number(summary?.header?.competitions?.[0]?.status?.period) || 1) >= 5 ? 2 : 3;
      atoEl.innerHTML = timeoutDotsHtml(tos.away, total);
      htoEl.innerHTML = timeoutDotsHtml(tos.home, total);
    } else {
      atoEl.innerHTML = ""; htoEl.innerHTML = "";
    }
  }
  // Team-color wash behind the hero logos (ESPN's edge-bleed look). The
  // color is set per team; CSS fades it out toward the center.
  const awayWrap = $("away-logo-holder"), homeWrap = $("home-logo-holder");
  if (awayWrap) awayWrap.style.setProperty("--wash", railColorOf(g.away, "#d50a0a"));
  if (homeWrap) homeWrap.style.setProperty("--wash", railColorOf(g.home, "#013369"));

  const as = $("away-score"), hs = $("home-score");
  const bump = (el: HTMLElement | null, v: string): void => {
    if (!el) return;
    if (el.textContent !== v && el.textContent !== "") {
      el.classList.remove("score-bump");
      void el.offsetWidth;
      el.classList.add("score-bump");
    }
    el.textContent = v;
  };
  bump(as, String(g.away.score));
  bump(hs, String(g.home.score));

  const badge = $("status-badge");
  const clock = $("inning-info");
  const possEl = $("poss-text");
  const sit = phase === "in" ? parseSituation(summary, g) : null;

  hideAllStatePanes();
  const dyn = $("dynamic-tab-label");

  if (isPostponed) {
    if (badge) { badge.textContent = "POSTPONED"; }
    if (clock) clock.textContent = "";
    if (possEl) possEl.textContent = "";
    if (dyn) dyn.textContent = "POSTPONED";
    const pane = $("postponed-content");
    if (pane) pane.style.display = "block";
    try { renderPostponed(g); } catch (e) { reportError("renderPostponed", e); }
  } else if (phase === "post") {
    if (badge) badge.textContent = "FINAL";
    if (clock) clock.textContent = g.period > 4 ? "F/OT" : "";
    if (possEl) possEl.textContent = "";
    if (dyn) dyn.textContent = "WRAP";
    const pane = $("final-content");
    if (pane) pane.style.display = "block";
    try { renderFinal(g); } catch (e) { reportError("renderFinal", e); }
  } else if (phase === "pre") {
    if (badge) badge.textContent = "";
    if (clock) clock.textContent = formatGameTime(g.date);
    if (possEl) possEl.textContent = "";
    if (dyn) dyn.textContent = "MATCHUP";
    const pane = $("pregame-content");
    if (pane) pane.style.display = "block";
    try { renderPregame(g); } catch (e) { reportError("renderPregame", e); }
  } else {
    if (badge) badge.textContent = "LIVE";
    if (clock) {
      // displayClock/period unverified live — fall back to latest play.
      let clk = g.displayClock, per = g.period;
      if (!clk || !per) {
        const lp = lastPlayOf(summary);
        if (lp) {
          if (!clk && lp.clock?.displayValue) clk = String(lp.clock.displayValue);
          if (!per && lp.period?.number) per = Number(lp.period.number);
        }
      }
      clock.textContent = `${clk || ""} ${periodLabel(per || 0)}`.trim() || "IN PROGRESS";
    }
    if (possEl) possEl.textContent = sit?.possText ? `BALL ON ${sit.possText.toUpperCase()}` : "";
    if (dyn) dyn.textContent = "LIVE";
    const pane = $("live-content");
    if (pane) pane.style.display = "block";
    if (!fieldBuilt) {
      buildFieldStatics(g);
      fieldBuilt = true;
      fitEzNames();
      try { (document as any).fonts?.ready?.then(fitEzNames); } catch { /* no-op */ }
    }
    const sitEl = $("situation");
    if (sitEl) {
      const show = !!(sit && sit.ddText);
      sitEl.style.display = show ? "" : "none";
      if (show && sitPlacement === null) placeSituationStrip();
      if (show) {
        const dd = $("sit-dd"), spot = $("sit-spot");
        if (dd) dd.textContent = sit!.ddText;
        if (spot) spot.textContent = sit!.possText || "—";
      }
    }
    try { renderField(summary, g, sit); } catch (e) { reportError("renderField", e); }
  }

  try { renderLinescore(g); } catch (e) { reportError("renderLinescore", e); }

  if ($("tab-box")?.classList.contains("tab-content-active")) {
    try { renderStatsTab(); } catch (e) { reportError("renderStatsTab", e); }
  }
  if ($("tab-plays")?.classList.contains("tab-content-active")) {
    try { renderPlaysTab(); } catch (e) { reportError("renderPlaysTab", e); }
  }
  if ($("tab-winprob")?.classList.contains("tab-content-active")) {
    void renderWinProb();
  }

  if (phase === "post") {
    gameIsTerminal = true;
    stopPolling();
  }
}

// ── Tabs / polling / postgame / init (ported) ─────────────────────────────

function setupTabs(): void {
  document.querySelectorAll(".tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetTab = (btn as HTMLElement).dataset.tab;
      if (!targetTab) return;
      document.body.classList.toggle("on-game-tab", targetTab === "game");
      document.body.classList.toggle("on-box-tab", targetTab === "box");
      document.body.classList.toggle("on-standings-tab", targetTab === "standings");
      document.querySelectorAll(".tab").forEach((t) => t.classList.remove("tab-active"));
      btn.classList.add("tab-active");
      document.querySelectorAll(".tab-content").forEach((c) => c.classList.remove("tab-content-active"));
      $(`tab-${targetTab}`)?.classList.add("tab-content-active");

      document.body.scrollTop = 0;
      document.documentElement.scrollTop = 0;
      const region = inlinePagerRegion();
      if (region) region.scrollTop = 0;

      if (targetTab === "box" && lastSummary) {
        statsAnimate = true;
        try { renderStatsTab(); } catch (e) { reportError("renderStatsTab", e); }
      }
      if (targetTab === "plays") {
        playsAnimate = true;
        if (lastSummary) {
          try { renderPlaysTab(); } catch (e) { reportError("renderPlaysTab", e); }
        }
        setPlaysView("scoring");
      }
      if (targetTab === "winprob") {
        wpAnimate = true;
        void renderWinProb();
      }
      if (targetTab === "standings") {
        setStandLeague(standActiveLeague);
      }
    });
  });
}

// How often to ask, by phase. A finished game's data is frozen, and a
// pregame payload changes a couple of times an hour — polling either at the
// live 10s cadence was pure waste (Joe).
function pollDelayMs(): number {
  const g = lastGame;
  if (!g) return 10000;
  if (g.phase === "in") return 10000;               // live: unchanged
  if (g.phase === "post") return 60000;             // final: a couple of confirmations, then stop
  // pregame: tighten as kickoff approaches
  const mins = (new Date(g.date).getTime() - Date.now()) / 60000;
  if (!isFinite(mins)) return 60000;
  if (mins <= 5) return 15000;
  if (mins <= 30) return 60000;
  return 180000;
}

function scheduleNextPoll(): void {
  if (pollInterval) clearTimeout(pollInterval);
  pollInterval = setTimeout(() => {
    void (async (): Promise<void> => {
      // Final games: confirm a couple of times (late stat corrections), then
      // stop polling altogether — nothing more is coming. Only count a
      // confirmation we ACTUALLY made: a backgrounded tab used to burn all
      // three without fetching, then stop polling for good.
      if (document.hidden || eventId == null) { scheduleNextPoll(); return; }
      if (lastGame?.phase === "post") {
        finalPollsDone++;
        if (finalPollsDone > 3) { stopPolling(); return; }
      }
      await fetchAndRender(eventId);
      scheduleNextPoll();
    })();
  }, pollDelayMs());
}

function startPolling(): void {
  finalPollsDone = 0;
  scheduleNextPoll();
}

function stopPolling(): void {
  if (pollInterval) {
    clearTimeout(pollInterval);
    pollInterval = null;
  }
}

async function maybeNotifyPostgame(g: NormGame): Promise<void> {
  if (postgameNotificationFired) return;
  if (g.phase !== "post") return;
  postgameNotificationFired = true;
  try {
    await fetch("/api/postgame-check", { method: "POST" });
  } catch (e) {
    console.error("postgame notify failed:", e);
  }
}

async function selectGameForThisPost(): Promise<string | null> {
  try {
    const res = await fetch("/api/post-game");
    if (res.ok) {
      const data: any = await res.json();
      if (data?.postType) postType = String(data.postType);
      if (data?.eventId) return String(data.eventId);
    }
  } catch { /* no bound game */ }
  return null;
}

function renderEndedState(): void {
  const host = $("loading-state");
  if (!host) return;
  host.innerHTML = `
    <div class="ended-display">
      <div class="ended-headline">Scoreboard Unavailable</div>
      <div class="ended-divider"></div>
      <div class="ended-text">This thread isn't linked to a game yet.</div>
      <div id="pick-game" class="pick-wrap"></div>
    </div>`;
  void offerGamePicker();
}

// Manual fallback when automatic recovery can't identify the game: show
// recent slates so the viewer can bind the thread themselves. Uses only the
// existing /api/schedule endpoint.
async function offerGamePicker(): Promise<void> {
  const box = $("pick-game");
  if (!box) return;
  const days: string[] = [];
  for (let i = 0; i < 8; i++) {
    const d = new Date(Date.now() - i * 86400000);
    days.push(d.toISOString().slice(0, 10));
  }
  const found: Array<{ id: string; label: string }> = [];
  const diag: string[] = [];
  for (const day of days) {
    if (found.length >= 12) break;
    // Plain first, then preseason and postseason slates — ESPN needs the
    // season type stated for those or it may return nothing.
    for (const st of ["", "1", "3"]) {
      let events: any[] = [];
      try {
        const res = await fetch(`/api/schedule?date=${day}${st ? `&st=${st}` : ""}`);
        if (!res.ok) {
          // The server writes its error message into the 500 body — surface
          // it so the app diagnoses itself.
          let why = "";
          try {
            const body = await res.text();
            try { why = String(JSON.parse(body)?.error || "").slice(0, 140); }
            catch { why = body.slice(0, 140); }
          } catch { /* body unreadable */ }
          if (diag.length < 2) diag.push(`HTTP ${res.status}${why ? `: ${why}` : ""}`);
          continue;
        }
        const data: any = await res.json();
        events = data?.events || [];
      } catch (e) {
        if (diag.length < 3) diag.push(`${day.slice(5)}: fetch threw`);
        continue;
      }
      if (events.length) console.log(`schedule ${day} st=${st || "-"}: ${events.length} events`);
      for (const ev of events) {
        const comp = ev?.competitions?.[0];
        const cs: any[] = comp?.competitors || [];
        const h = cs.find((c) => c?.homeAway === "home")?.team?.abbreviation || "";
        const a = cs.find((c) => c?.homeAway === "away")?.team?.abbreviation || "";
        if (!h || !a) continue;
        if (!found.some((f) => f.id === String(ev.id))) {
          found.push({ id: String(ev.id), label: `${a} @ ${h} · ${day.slice(5)}` });
        }
      }
      if (events.length) break; // this day's slate found; no need for other season types
    }
  }
  if (!found.length) {
    const why = diag.length ? diag.join(" · ") : "all slates came back empty";
    box.innerHTML = `<div class="pick-note">No recent games found to link.</div>` +
      `<div class="pick-note pick-diag">(${escapeHtml(why)})</div>`;
    return;
  }
  box.innerHTML = '<div class="pick-note">Pick the game this thread is for:</div>' +
    found.slice(0, 12).map((f) =>
      `<button class="pick-btn" type="button" data-ev="${escapeHtml(f.id)}">${escapeHtml(f.label)}</button>`
    ).join("");
  box.querySelectorAll<HTMLElement>(".pick-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.getAttribute("data-ev");
      if (!id) return;
      eventId = id;
      const loading = $("loading-state");
      if (loading) loading.innerHTML = '<div class="loading-spinner"></div><div class="loading-text">Loading scoreboard…</div>';
      void fetchAndRender(id).then(() => { if (!gameIsTerminal) startPolling(); });
    });
  });
}

function renderUnreachableState(): void {
  const host = $("loading-state");
  if (!host || !firstRender) return; // only before anything has painted
  host.innerHTML = `
    <div class="ended-display">
      <div class="ended-headline">Scoreboard Unavailable</div>
      <div class="ended-divider"></div>
      <div class="ended-text">Couldn't reach the scoreboard service. Retrying automatically…</div>
    </div>`;
}

async function fetchAndRender(id: string): Promise<void> {
  try {
    const res = await fetch(`/api/game/${id}`);
    const data = await res.json();
    if (!data?.header) {
      console.error("Game data unavailable");
      // Never painted and the payload is unusable → say so instead of
      // leaving the spinner up forever (polling keeps retrying).
      renderUnreachableState();
      return;
    }
    render(data);
  } catch (e) {
    console.error("fetchAndRender error:", e);
    renderUnreachableState();
  }
}

(async (): Promise<void> => {
  document.body.classList.add("on-game-tab");
  setupTabs();
  setupPlaysToggle();
  setupWinProbDismiss();
  setupThemeToggle();
  setupExpand();
  setupGraphButton();
  setupTvButton();
  setupStandings();
  setupInlinePager();
  $("replay-play-btn")?.addEventListener("click", replayLastPlay);

  document.addEventListener("visibilitychange", () => {
    // Refresh on return even if polling has stopped (terminal game): cheap,
    // once, and guarantees the view isn't stale after a long background.
    if (!document.hidden && eventId != null) void fetchAndRender(eventId);
  });

  eventId = await selectGameForThisPost();
  if (!eventId) {
    renderEndedState();
    return;
  }
  await fetchAndRender(eventId);

  if (!gameIsTerminal) startPolling();
})();

export {};